27	  /** enclosing tube radius (0 = open environment such as a drum/basin/chamber) */
28	  tube: number;
29	  tubeKind: TubeKind;
30	  /** auto-propulsion speed (units / s) */
31	  speed: number;
32	  /** coin counter shown in the locked reference screenshot of this stage */
33	  refCoins: number;
34	  interactive: boolean;
35	  /** banking strength multiplier */
36	  bank: number;
37	}
38	
39	export interface CourseSample {
40	  s: number;
41	  pos: THREE.Vector3;
42	  tan: THREE.Vector3;
43	  up: THREE.Vector3;
44	  right: THREE.Vector3;
45	}
46	
47	export const STAGE_TITLES: Record<StageId, string> = {
48	  '01': 'INSIDE THE WASHING MACHINE',
49	  '02': 'WHIRLPOOL TUMBLE',
50	  '03': 'WHIRLPOOL TWIRL',
51	  '04': 'THROUGH THE FIVE ARROWS',
52	  '05': 'FLOW INTO THE CURRENT',
53	  '06': 'CREST THE RINSE ARCH',
54	  '07': 'DIVE THE WASHER TUBE',
55	  '08': 'FINAL SPIN CHAMBER',
56	  '09': 'RIDE THE FINAL WAVE',
57	  '10': 'SLIDE INTO HIDING',
58	  '11': 'SAFELY HOME',
59	};
