  group.add(swirl);

  return {
    group,
    surface,
    swirl,
    uniforms,
    swirlUniforms,
    heightAt(x, z, t) {
      const amp = 0.3 + (uniforms.uAgitation.value as number) * 0.5;
      return (
        dA.waterY +
        amp * (0.55 * Math.sin(x * 1.1 + z * 0.6 + t * 1.8) + 0.35 * Math.sin(-x * 0.7 + z * 1.5 - t * 2.3) + 0.22 * Math.sin(x * 2.3 - z * 1.9 + t * 3.1))
      );
    },
  };
}

